<?php
session_start(); require 'config/database.php'; require 'lib_security.php';
$msg=$error='';
$programs=$pdo->query("SELECT * FROM programs WHERE active=1 ORDER BY FIELD(level,'HSSC','BS','ADP'),name")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){ verifyCsrf();
 $name=trim($_POST['name']); $father=trim($_POST['father_name']); $cnic=trim($_POST['cnic']); $email=trim($_POST['email']); $phone=trim($_POST['phone']); $program=(int)$_POST['program_id']; $session=trim($_POST['admission_session']??''); $marks=(float)$_POST['previous_marks']; $total=(float)$_POST['previous_total'];
 if($name===''||$father===''||$email===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$program<1||$total<=0||!preg_match('/^\d{4}-\d{2}$/',$session)){$error='Please fill all required fields correctly.';} else {
  $appNo='IMCB-'.date('Y').'-'.str_pad((string)random_int(1,99999),5,'0',STR_PAD_LEFT);
  try{$q=$pdo->prepare('INSERT INTO admission_applications(application_no,name,father_name,cnic,email,phone,program_id,previous_marks,previous_total,merit_score,status,admission_session) VALUES(?,?,?,?,?,?,?,?,?,? ,"pending",?)');$q->execute([$appNo,$name,$father,$cnic,$email,$phone,$program,$marks,$total,$total>0?round(($marks/$total)*100,2):0,$session]);$msg="Application submitted successfully. Application No: $appNo";}catch(Throwable $e){$error='Could not submit application. CNIC/email may already be registered.';}
 }
}
$pageTitle='Online Admission'; require 'includes/header.php';
